#!/usr/bin/env python3
"""
patch_coverage.py — Calculate and report patch coverage on changed Go lines.

Part of Phase 1 of issue hivecommons/hive#14161.
Mechanics:
1. Diff: git diff -U0 --no-color <base> <head>
   Excludes: _test.go, testdata/, generated files, blank lines, single-line comments.
2. Coverprofiles: Parse all blocks from specified profile(s) and aggregate counts.
3. Map each added line to coverprofile blocks:
   - covered if any enclosing block has count > 0
   - uncovered if every enclosing block has count == 0
   - unscored if no enclosing block (comments, declarations, excluded packages)
4. Score = covered / (covered + uncovered).
5. Post or edit-in-place comment on PR if PR number is given.
6. Write summary to GITHUB_STEP_SUMMARY.
"""

from __future__ import annotations

import argparse
import glob
import json
import os
import re
import shutil
import subprocess
import sys
import urllib.error
import urllib.request
from typing import Dict, List, Optional, Set, Tuple

MARKER = "<!-- hive-patch-coverage -->"

GENERATED_FILE_PATTERNS = [
    re.compile(r".*\.pb\.go$"),
    re.compile(r".*_generated\.go$"),
    re.compile(r".*zz_generated.*\.go$"),
]

GENERATED_CONTENT_PATTERNS = [
    re.compile(r"^// Code generated .* DO NOT EDIT\.$", re.IGNORECASE),
    re.compile(r"^// Code generated by .* DO NOT EDIT", re.IGNORECASE),
    re.compile(r"^/\* Code generated .* DO NOT EDIT", re.IGNORECASE),
    re.compile(r"^// DO NOT EDIT", re.IGNORECASE),
    re.compile(r"^// auto-generated", re.IGNORECASE),
    re.compile(r"^// GENERATED", re.IGNORECASE),
]


class ProfileBlock:
    __slots__ = ("file", "start_line", "start_col", "end_line", "end_col", "stmts", "count")

    def __init__(
        self,
        file: str,
        start_line: int,
        start_col: int,
        end_line: int,
        end_col: int,
        stmts: int,
        count: int,
    ) -> None:
        self.file = file
        self.start_line = start_line
        self.start_col = start_col
        self.end_line = end_line
        self.end_col = end_col
        self.stmts = stmts
        self.count = count


def normalize_path(path: str) -> str:
    p = path.replace("\\", "/").strip()
    if p.startswith("./"):
        p = p[2:]
    if p.startswith("src/"):
        p = p[4:]
    for prefix in ("github.com/hivecommons/hive/", "github.com/kubestellar/hive/"):
        if p.startswith(prefix):
            p = p[len(prefix) :]
    return p


def format_ranges(lines: List[int]) -> str:
    if not lines:
        return ""
    sorted_lines = sorted(set(lines))
    ranges: List[str] = []
    start = sorted_lines[0]
    end = start
    for l in sorted_lines[1:]:
        if l == end + 1:
            end = l
        else:
            if start == end:
                ranges.append(str(start))
            else:
                ranges.append(f"{start}-{end}")
            start = end = l
    if start == end:
        ranges.append(str(start))
    else:
        ranges.append(f"{start}-{end}")
    return ", ".join(ranges)


def is_generated_file(repo_root: str, rel_path: str) -> bool:
    for pat in GENERATED_FILE_PATTERNS:
        if pat.match(rel_path):
            return True
    candidates = [
        os.path.join(repo_root, rel_path),
        os.path.join(repo_root, "src", rel_path),
    ]
    full_path = None
    for cand in candidates:
        if os.path.isfile(cand):
            full_path = cand
            break
    if full_path and os.path.isfile(full_path):
        try:
            with open(full_path, "r", encoding="utf-8", errors="ignore") as f:
                for idx, line in enumerate(f):
                    if idx > 50:
                        break
                    s = line.strip()
                    for cpat in GENERATED_CONTENT_PATTERNS:
                        if cpat.match(s):
                            return True
        except Exception:
            pass
    return False


def is_excluded_file(repo_root: str, file_path: str) -> bool:
    if not file_path.endswith(".go"):
        return True
    if file_path.endswith("_test.go"):
        return True
    parts = file_path.replace("\\", "/").split("/")
    if "testdata" in parts:
        return True
    if is_generated_file(repo_root, file_path):
        return True
    return False


def get_file_lines(repo_root: str, file_path: str) -> Dict[int, str]:
    candidates = [
        os.path.join(repo_root, file_path),
        os.path.join(repo_root, "src", file_path),
    ]
    full_path = None
    for cand in candidates:
        if os.path.isfile(cand):
            full_path = cand
            break
    res: Dict[int, str] = {}
    if full_path and os.path.isfile(full_path):
        try:
            with open(full_path, "r", encoding="utf-8", errors="ignore") as f:
                for idx, line in enumerate(f, start=1):
                    res[idx] = line
        except Exception:
            pass
    return res


def get_changed_lines(
    repo_root: str, base_ref: str, head_ref: str
) -> Tuple[Dict[str, Set[int]], Dict[str, str]]:
    """
    Returns (changed_lines, display_paths).
    changed_lines: {normalized_path: set_of_added_line_numbers}
    display_paths: {normalized_path: repo_relative_display_path}
    """
    diff_base = base_ref
    try:
        mb = subprocess.check_output(
            ["git", "merge-base", base_ref, head_ref],
            cwd=repo_root,
            stderr=subprocess.DEVNULL,
            text=True,
        ).strip()
        if mb:
            diff_base = mb
    except Exception:
        pass

    try:
        cmd = ["git", "diff", "-U0", "--no-color", diff_base, head_ref]
        diff_out = subprocess.check_output(cmd, cwd=repo_root, text=True, errors="ignore")
    except Exception as e:
        print(f"Warning: git diff failed: {e}", file=sys.stderr)
        return {}, {}

    changed_lines: Dict[str, Set[int]] = {}
    display_paths: Dict[str, str] = {}
    current_norm: Optional[str] = None
    file_lines: Dict[int, str] = {}
    hunk_re = re.compile(r"^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@")

    for line in diff_out.splitlines():
        if line.startswith("+++ b/"):
            raw_path = line[6:].strip()
            if raw_path == "/dev/null" or is_excluded_file(repo_root, raw_path):
                current_norm = None
            else:
                norm = normalize_path(raw_path)
                current_norm = norm
                display_paths[norm] = raw_path
                if current_norm not in changed_lines:
                    changed_lines[current_norm] = set()
                file_lines = get_file_lines(repo_root, raw_path)
            continue
        elif line.startswith("+++ "):
            current_norm = None
            continue

        if current_norm is None:
            continue

        m = hunk_re.match(line)
        if m:
            start_line = int(m.group(1))
            count = int(m.group(2)) if m.group(2) is not None else 1
            for l in range(start_line, start_line + count):
                line_text = file_lines.get(l, "").strip()
                # Skip blank lines, comments, and package/import declarations
                if not line_text or line_text.startswith("//"):
                    continue
                if line_text.startswith("package ") or line_text == "package":
                    continue
                if line_text.startswith("import ") or line_text == "import (" or line_text == "import":
                    continue
                changed_lines[current_norm].add(l)

    # Filter out files with no added lines
    filtered_changed = {f: lines for f, lines in changed_lines.items() if lines}
    return filtered_changed, display_paths


def parse_coverprofiles(profile_paths: List[str]) -> Dict[str, List[ProfileBlock]]:
    """
    Parses coverprofile files, aggregating counts for identical blocks across shards.
    Returns {normalized_path: list_of_ProfileBlock}.
    """
    # Key: (norm_file, start_line, start_col, end_line, end_col, stmts) -> total_count
    aggregated: Dict[Tuple[str, int, int, int, int, int], int] = {}

    for path in profile_paths:
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith("mode:"):
                        continue
                    parts = line.split()
                    if len(parts) != 3:
                        continue
                    loc_part, stmts_str, count_str = parts[0], parts[1], parts[2]
                    try:
                        stmts = int(stmts_str)
                        count = int(count_str)
                    except ValueError:
                        continue

                    colon_idx = loc_part.rfind(":")
                    if colon_idx == -1:
                        continue
                    raw_file = loc_part[:colon_idx]
                    loc = loc_part[colon_idx + 1 :]

                    try:
                        start_part, end_part = loc.split(",")
                        start_line, start_col = map(int, start_part.split("."))
                        end_line, end_col = map(int, end_part.split("."))
                    except ValueError:
                        continue

                    norm_file = normalize_path(raw_file)
                    key = (norm_file, start_line, start_col, end_line, end_col, stmts)
                    aggregated[key] = aggregated.get(key, 0) + count
        except Exception as e:
            print(f"Warning: error reading profile {path}: {e}", file=sys.stderr)

    by_file: Dict[str, List[ProfileBlock]] = {}
    for (norm_file, start_line, start_col, end_line, end_col, stmts), count in aggregated.items():
        block = ProfileBlock(norm_file, start_line, start_col, end_line, end_col, stmts, count)
        by_file.setdefault(norm_file, []).append(block)

    return by_file


def score_patch_coverage(
    changed_lines: Dict[str, Set[int]],
    profiles_by_file: Dict[str, List[ProfileBlock]],
) -> Tuple[int, int, Dict[str, List[int]], Dict[str, List[int]]]:
    """
    Scores added lines against coverprofile blocks.
    Returns: (total_covered, total_uncovered, covered_by_file, uncovered_by_file)
    """
    total_covered = 0
    total_uncovered = 0
    covered_by_file: Dict[str, List[int]] = {}
    uncovered_by_file: Dict[str, List[int]] = {}

    for norm_file, lines in changed_lines.items():
        blocks = profiles_by_file.get(norm_file)
        if blocks is None:
            # Fallback suffix match
            for pf, pblocks in profiles_by_file.items():
                if pf.endswith("/" + norm_file) or norm_file.endswith("/" + pf):
                    blocks = pblocks
                    break

        cov_lines = []
        uncov_lines = []

        if blocks:
            for l in sorted(lines):
                enclosing = [b for b in blocks if b.start_line <= l <= b.end_line]
                if not enclosing:
                    # Unscored (outside function / declarations / comments)
                    continue
                if any(b.count > 0 for b in enclosing):
                    cov_lines.append(l)
                else:
                    uncov_lines.append(l)

        if cov_lines:
            covered_by_file[norm_file] = cov_lines
            total_covered += len(cov_lines)
        if uncov_lines:
            uncovered_by_file[norm_file] = uncov_lines
            total_uncovered += len(uncov_lines)

    return total_covered, total_uncovered, covered_by_file, uncovered_by_file


def generate_comment_body(
    percent: float,
    covered: int,
    uncovered: int,
    uncovered_by_file: Dict[str, List[int]],
    display_paths: Dict[str, str],
    min_percent: float,
    min_uncovered: int,
    is_advisory: bool,
) -> str:
    if uncovered == 0:
        return (
            f"{MARKER}\n"
            "### Patch Coverage: 100.0% :white_check_mark:\n\n"
            "All changed Go statements are covered by tests."
        )

    status_tag = "(advisory)" if is_advisory else ""
    lines = [
        MARKER,
        f"### Patch Coverage: {percent:.1f}% {status_tag}".strip(),
        "",
        "The following changed Go statements have no test coverage:",
        "",
        "| File | Uncovered Lines |",
        "| :--- | :--- |",
    ]
    for norm_file in sorted(uncovered_by_file.keys()):
        disp = display_paths.get(norm_file, norm_file)
        rngs = format_ranges(uncovered_by_file[norm_file])
        lines.append(f"| `{disp}` | {rngs} |")

    lines.extend([
        "",
        "<details>",
        "<summary>Details</summary>",
        "",
        f"- **Covered statements:** {covered}",
        f"- **Uncovered statements:** {uncovered}",
        f"- **Patch coverage:** {percent:.1f}% (threshold: {min_percent:.1f}%, min uncovered: {min_uncovered})",
        "",
        "*Phase 1 is advisory. In Phase 2, PRs with patch coverage below 80% and ≥5 uncovered statements will fail the coverage gate.*",
        "</details>",
    ])
    return "\n".join(lines)


def write_step_summary(
    summary_path: str,
    percent: float,
    covered: int,
    uncovered: int,
    uncovered_by_file: Dict[str, List[int]],
    display_paths: Dict[str, str],
    min_percent: float,
    min_uncovered: int,
    is_advisory: bool,
) -> None:
    if not summary_path:
        return

    lines = [
        "## Patch Coverage on Changed Go Lines",
        "",
    ]
    if covered + uncovered == 0:
        lines.append("No executable changed Go statements to score.")
    elif uncovered == 0:
        lines.extend([
            "- **Patch coverage:** 100.0% :white_check_mark:",
            f"- **Covered statements:** {covered}",
            "- **Uncovered statements:** 0",
        ])
    else:
        status_str = (
            "Advisory"
            if is_advisory
            else (
                "Failed"
                if (percent < min_percent and uncovered >= min_uncovered)
                else "Passed"
            )
        )
        lines.extend([
            f"- **Patch coverage:** {percent:.1f}% ({covered} / {covered + uncovered} statements covered)",
            f"- **Uncovered statements:** {uncovered}",
            f"- **Status:** {status_str} (threshold: {min_percent:.1f}%, min uncovered: {min_uncovered})",
            "",
            "### Uncovered lines by file",
            "",
            "| File | Uncovered Lines |",
            "| :--- | :--- |",
        ])
        for norm_file in sorted(uncovered_by_file.keys()):
            disp = display_paths.get(norm_file, norm_file)
            rngs = format_ranges(uncovered_by_file[norm_file])
            lines.append(f"| `{disp}` | {rngs} |")

    lines.append("")
    try:
        with open(summary_path, "a", encoding="utf-8") as f:
            f.write("\n".join(lines) + "\n")
    except Exception as e:
        print(f"Warning: could not write step summary to {summary_path}: {e}", file=sys.stderr)


def _rest_request(method: str, path: str, body: Optional[bytes] = None) -> Tuple[bool, str, Dict[str, str]]:
    """Call the GitHub REST API without the gh CLI.

    Self-hosted runner images do not ship gh, so the comment upsert falls back
    to plain HTTPS with the same token gh would have read (GH_TOKEN, else
    GITHUB_TOKEN) against GITHUB_API_URL. Returns (ok, response body, headers).
    """
    api = os.environ.get("GITHUB_API_URL", "https://api.github.com").rstrip("/")
    token = os.environ.get("GH_TOKEN") or os.environ.get("GITHUB_TOKEN") or ""
    headers = {"Accept": "application/vnd.github+json", "User-Agent": "hive-patch-coverage"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    if body is not None:
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(f"{api}/{path}", data=body, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return True, resp.read().decode("utf-8", errors="ignore"), dict(resp.headers)
    except urllib.error.HTTPError as e:
        return False, f"HTTP {e.code}: {e.read().decode('utf-8', errors='ignore').strip()}", {}
    except Exception as e:  # URLError, timeout
        return False, str(e), {}


def _find_marker_comment_id(repo: str, pr: int) -> Optional[str]:
    if shutil.which("gh"):
        cmd = [
            "gh",
            "api",
            f"repos/{repo}/issues/{pr}/comments?per_page=100",
            "--paginate",
            "--jq",
            f'.[] | select(.body | contains("{MARKER}")) | .id',
        ]
        res = subprocess.run(cmd, capture_output=True, text=True, check=False)
        if res.returncode == 0 and res.stdout.strip():
            return res.stdout.strip().splitlines()[0]
        return None
    page = 1
    while True:
        ok, text, headers = _rest_request("GET", f"repos/{repo}/issues/{pr}/comments?per_page=100&page={page}")
        if not ok:
            raise RuntimeError(text)
        comments = json.loads(text) if text.strip() else []
        for c in comments:
            if MARKER in (c.get("body") or ""):
                return str(c.get("id"))
        if 'rel="next"' not in headers.get("Link", "") or not comments:
            return None
        page += 1


def _write_api(method: str, path: str, req_bytes: bytes) -> Tuple[bool, str]:
    if shutil.which("gh"):
        res = subprocess.run(
            ["gh", "api", "-X", method, path, "--input", "-"],
            input=req_bytes,
            capture_output=True,
            check=False,
        )
        return res.returncode == 0, res.stderr.decode("utf-8", errors="ignore").strip()
    ok, text, _ = _rest_request(method, path, req_bytes)
    return ok, "" if ok else text


def upsert_comment(repo: str, pr: int, body: str, uncovered: int, dry_run: bool = False) -> None:
    if dry_run:
        print(f"[DRY RUN] Would update/post comment on {repo}#{pr}:")
        print(body)
        return

    # Check for existing comment carrying the marker
    comment_id: Optional[str] = None
    try:
        comment_id = _find_marker_comment_id(repo, pr)
    except Exception as e:
        print(f"::notice::Could not query comments on PR #{pr}: {e}", file=sys.stderr)

    req_bytes = json.dumps({"body": body}).encode("utf-8")

    if comment_id:
        try:
            ok, err = _write_api("PATCH", f"repos/{repo}/issues/comments/{comment_id}", req_bytes)
            if ok:
                print(f"Updated patch coverage comment on PR #{pr} (comment ID {comment_id})")
            else:
                print(f"::notice::Could not update patch coverage comment (ID {comment_id}): {err}", file=sys.stderr)
        except Exception as e:
            print(f"::notice::Error updating patch coverage comment: {e}", file=sys.stderr)
    else:
        # If no previous comment exists and there are no uncovered statements, don't post a comment
        if uncovered == 0:
            return
        try:
            ok, err = _write_api("POST", f"repos/{repo}/issues/{pr}/comments", req_bytes)
            if ok:
                print(f"Posted patch coverage comment on PR #{pr}")
            else:
                print(f"::notice::Could not post patch coverage comment on PR #{pr}: {err}", file=sys.stderr)
        except Exception as e:
            print(f"::notice::Error posting patch coverage comment: {e}", file=sys.stderr)


def resolve_base_ref(repo_root: str, base_arg: Optional[str]) -> str:
    if base_arg:
        # Verify base_arg is resolvable
        try:
            subprocess.check_call(
                ["git", "rev-parse", "-q", "--verify", base_arg],
                cwd=repo_root,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            return base_arg
        except Exception:
            pass

    # Check if HEAD^2 exists (merge commit)
    try:
        subprocess.check_call(
            ["git", "rev-parse", "-q", "--verify", "HEAD^2"],
            cwd=repo_root,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        return "HEAD^1"
    except Exception:
        pass

    # Check common base branches
    for candidate in ["origin/v5", "v5", "origin/main", "main", "HEAD~1"]:
        try:
            subprocess.check_call(
                ["git", "rev-parse", "-q", "--verify", candidate],
                cwd=repo_root,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            return candidate
        except Exception:
            continue

    return "HEAD"


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Calculate and report patch coverage on changed Go lines."
    )
    parser.add_argument("--base", default=None, help="Base git ref or commit SHA")
    parser.add_argument("--head", default="HEAD", help="Head git ref (default: HEAD)")
    parser.add_argument(
        "--profile",
        action="append",
        default=[],
        help="Coverprofile file or pattern (can be specified multiple times)",
    )
    parser.add_argument(
        "--profile-dir",
        default=None,
        help="Directory containing coverprofiles",
    )
    parser.add_argument(
        "--min-percent",
        type=float,
        default=80.0,
        help="Minimum patch coverage percentage (default: 80.0)",
    )
    parser.add_argument(
        "--min-uncovered",
        type=int,
        default=5,
        help="Minimum uncovered statements before threshold fails (default: 5)",
    )
    parser.add_argument(
        "--advisory",
        action="store_true",
        default=False,
        help="Advisory mode: exit 0 even if threshold is not met (Phase 1 default)",
    )
    parser.add_argument(
        "--pr",
        type=int,
        default=None,
        help="Pull request number (or set via PR_NUMBER env var)",
    )
    parser.add_argument(
        "--repo",
        default=None,
        help="GitHub repo slug owner/name (or set via GITHUB_REPOSITORY env var)",
    )
    parser.add_argument(
        "--summary-file",
        default=None,
        help="Path to write GitHub step summary (or set via GITHUB_STEP_SUMMARY env var)",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        default=False,
        help="Print planned comment without making API calls",
    )

    args = parser.parse_args()

    try:
        repo_root = subprocess.check_output(
            ["git", "rev-parse", "--show-toplevel"],
            text=True,
        ).strip()
    except Exception:
        repo_root = os.getcwd()

    base_ref = resolve_base_ref(repo_root, args.base)
    head_ref = args.head

    pr_number = args.pr
    if pr_number is None and os.environ.get("PR_NUMBER"):
        try:
            pr_number = int(os.environ["PR_NUMBER"])
        except ValueError:
            pass

    repo_slug = args.repo or os.environ.get("GITHUB_REPOSITORY") or "hivecommons/hive"
    summary_file = args.summary_file or os.environ.get("GITHUB_STEP_SUMMARY")

    # Resolve coverprofiles
    profile_inputs: List[str] = []
    for p in args.profile:
        for part in p.split():
            profile_inputs.append(part)

    resolved_profiles: List[str] = []
    for p in profile_inputs:
        matched = glob.glob(p)
        if matched:
            resolved_profiles.extend(matched)
        elif os.path.isfile(p):
            resolved_profiles.append(p)

    if args.profile_dir and os.path.isdir(args.profile_dir):
        resolved_profiles.extend(glob.glob(os.path.join(args.profile_dir, "coverage*.out")))

    # Fallback search if no profile specified or found
    if not resolved_profiles:
        for cand in [
            "shards/coverage-merged.out",
            "shards/coverage-*.out",
            "coverage-merged.out",
            "coverage-*.out",
            "coverage.out",
        ]:
            matched = glob.glob(cand)
            if matched:
                resolved_profiles.extend(matched)
                break

    # 1. Get changed lines from git diff
    changed_lines, display_paths = get_changed_lines(repo_root, base_ref, head_ref)

    if not changed_lines:
        print("Patch coverage: No changed Go lines to score.")
        if summary_file:
            write_step_summary(
                summary_file, 100.0, 0, 0, {}, {}, args.min_percent, args.min_uncovered, args.advisory
            )
        return 0

    # 2. Parse coverprofiles
    profiles_by_file = parse_coverprofiles(resolved_profiles)

    # 3. Score patch coverage
    covered, uncovered, covered_by_file, uncovered_by_file = score_patch_coverage(
        changed_lines, profiles_by_file
    )
    total_scored = covered + uncovered

    if total_scored == 0:
        percent = 100.0
    else:
        percent = (covered / total_scored) * 100.0

    threshold_failed = (percent < args.min_percent) and (uncovered >= args.min_uncovered)

    # Output to stdout
    print("=" * 60)
    print("Patch Coverage Summary:")
    print(f"  Base ref: {base_ref}")
    print(f"  Head ref: {head_ref}")
    print(f"  Profiles parsed: {len(resolved_profiles)}")
    print(f"  Changed Go files scored: {len(changed_lines)}")
    print(f"  Scored statements: {total_scored} ({covered} covered, {uncovered} uncovered)")
    print(f"  Patch coverage: {percent:.1f}%")
    print(f"  Threshold: >= {args.min_percent:.1f}% (min uncovered: {args.min_uncovered})")

    if threshold_failed:
        if args.advisory:
            print("  Result: ADVISORY (threshold not met; gate is advisory in Phase 1)")
        else:
            print("  Result: FAILED (threshold not met)")
    else:
        print("  Result: PASS")

    if uncovered_by_file:
        print("\nUncovered Go lines:")
        for norm_file in sorted(uncovered_by_file.keys()):
            disp = display_paths.get(norm_file, norm_file)
            rngs = format_ranges(uncovered_by_file[norm_file])
            print(f"  {disp}: {rngs}")
    print("=" * 60)

    # Write step summary
    if summary_file:
        write_step_summary(
            summary_file,
            percent,
            covered,
            uncovered,
            uncovered_by_file,
            display_paths,
            args.min_percent,
            args.min_uncovered,
            args.advisory,
        )

    # Post or update PR comment if PR number is available
    if pr_number:
        comment_body = generate_comment_body(
            percent,
            covered,
            uncovered,
            uncovered_by_file,
            display_paths,
            args.min_percent,
            args.min_uncovered,
            args.advisory,
        )
        upsert_comment(repo_slug, pr_number, comment_body, uncovered, dry_run=args.dry_run)

    if threshold_failed and not args.advisory:
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
